(4908992, 712877, 83650, '<td valign="top">Horse seems a bit distant and competes for attention with all the other stuff surrounding him.</td>', 'Horse seems a bit distant and competes for attention with all the other stuff surrounding him.', '2008-08-25 03:29:21.000000', NULL, 1),
(4908993, 713730, 83650, '<td valign="top">I know you''re going for the shoehorn here, so good luck.  no vote from me</td>', 'I know you''re going for the shoehorn here, so good luck.  no vote from me', '2008-08-25 03:30:05.000000', NULL, 1),
(4908999, 713591, 83650, '<td valign="top">A greater dof might have been in order since most of his head is in focus already.  I''m referring to his mouth area.</td>', 'A greater dof might have been in order since most of his head is in focus already.  I''m referring to his mouth area.', '2008-08-25 03:33:47.000000', NULL, 1),
(4909000, 713763, 83650, '<td valign="top">That''s a skinny lookin'' horse!  10mm @ 1 foot?</td>', 'That''s a skinny lookin'' horse!  10mm @ 1 foot?', '2008-08-25 03:34:57.000000', NULL, 1),
(4909002, 713310, 83650, '<td valign="top">I''m guessing this one is a contender for the front page.</td>', 'I''m guessing this one is a contender for the front page.', '2008-08-25 03:35:54.000000', NULL, 1),
(4909003, 713583, 83650, '<td valign="top">Good composition.  A few tweaks in tonal contrast on the horse''s body would have made this one shine.</td>', 'Good composition.  A few tweaks in tonal contrast on the horse''s body would have made this one shine.', '2008-08-25 03:37:48.000000', NULL, 1),
(4909005, 712654, 83650, '<td valign="top">Seems that your camera may have exposed for the horse because the grass/weeds are very bright.  A faster shutter speed would have made that whipping mane look cool.</td>', 'Seems that your camera may have exposed for the horse because the grass/weeds are very bright.  A faster shutter speed would have made that whipping mane look cool.', '2008-08-25 03:39:39.000000', NULL, 1),
(4909007, 713687, 83650, '<td valign="top">This is one of those shots where as soon as it loads, there isn''t anything to offer on improvements.</td>', 'This is one of those shots where as soon as it loads, there isn''t anything to offer on improvements.', '2008-08-25 03:40:39.000000', NULL, 1),
(4909026, 713587, 49109, '<td valign="top">I wonder how often that happens (a jockey losing his whip). Lucky capture! Nice color and good focus. had corrected the tilt.</td>', 'I wonder how often that happens (a jockey losing his whip). Lucky capture! Nice color and good focus. had corrected the tilt.', '2008-08-25 04:02:16.000000', NULL, 1),
(4909027, 713591, 49109, '<td valign="top">focus is slightly off, crop is very tight</td>', 'focus is slightly off, crop is very tight', '2008-08-25 04:02:56.000000', NULL, 1),
(4909033, 713771, 49109, '<td valign="top">way too much noise reduction used here</td>', 'way too much noise reduction used here', '2008-08-25 04:05:35.000000', NULL, 1),
(4909041, 713153, 49109, '<td valign="top">very interesting study. will probably get hammered, but I like it</td>', 'very interesting study. will probably get hammered, but I like it', '2008-08-25 04:10:47.000000', NULL, 1),
