(4909070, 712268, 79955, '<td valign="top">Sharpness could have been crisper. The extreme tight crop does not do it for me.</td>', 'Sharpness could have been crisper. The extreme tight crop does not do it for me.', '2008-08-25 04:27:53.000000', NULL, 1),
(4909072, 713503, 79955, '<td valign="top">A little oversharpened for my taste , but I like the image overall. nice job. 7</td>', 'A little oversharpened for my taste , but I like the image overall. nice job. 7', '2008-08-25 04:29:01.000000', NULL, 1),
