(4909076, 713382, 79955, '<td valign="top">The processing is overdone IMO, Prefer a toned down version.</td>', 'The processing is overdone IMO, Prefer a toned down version.', '2008-08-25 04:30:39.000000', NULL, 1),
(4909078, 713505, 79955, '<td valign="top">Nice action &amp; timing. 6</td>', 'Nice action & timing. 6', '2008-08-25 04:31:03.000000', NULL, 1),
(4909079, 713703, 79955, '<td valign="top">Sharpness a little off, too much saturation also.</td>', 'Sharpness a little off, too much saturation also.', '2008-08-25 04:31:35.000000', NULL, 1),
