(4909094, 713675, 47791, '<td valign="top">Very clean image but spoilt somewhat by the barbed wire.</td>', 'Very clean image but spoilt somewhat by the barbed wire.', '2008-08-25 04:43:38.000000', NULL, 1),
(4909095, 713641, 47791, '<td valign="top">Good DOF and the colours came out really well.</td>', 'Good DOF and the colours came out really well.', '2008-08-25 04:44:10.000000', NULL, 1),
