(4909768, 713174, 36999, '<td valign="top">slippy?  nice pose, I like what the treatment did to his mane &amp; tail and the foliage but it is a bit over the top for his body.  It makes for a killer photo illustration tho.  This horse has a nice kind and interested eye.</td>', 'slippy?  nice pose, I like what the treatment did to his mane & tail and the foliage but it is a bit over the top for his body.  It makes for a killer photo illustration tho.  This horse has a nice kind and interested eye.', '2008-08-25 13:39:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4909769, 713187, 14867, '<td valign="top">You probably exposed for the shadows, the result is that de background (and even a part of the horse) are completely blown out. In advanced editing, it''s normally possible to improve that.<br/>This said, the horse''s fur is cool.</td>', 'You probably exposed for the shadows, the result is that de background (and even a part of the horse) are completely blown out. In advanced editing, it''s normally possible to improve that.This said, the horse''s fur is cool.', '2008-08-25 13:40:13.000000', NULL, 1),
(4909770, 713028, 36999, '<td valign="top">more room for his ears and nose!  that would have also given you more chest and neck showing so it didn''t have the ''floating heaad'' syndrome.  Nice exposure and sharpness and nice fo have his ears up and not focused exactly on you.</td>', 'more room for his ears and nose!  that would have also given you more chest and neck showing so it didn''t have the ''floating heaad'' syndrome.  Nice exposure and sharpness and nice fo have his ears up and not focused exactly on you.', '2008-08-25 13:41:33.000000', NULL, 1),
(4909771, 713662, 36999, '<td valign="top">or fly removal!  nice exposure, sharpness and composition</td>', 'or fly removal!  nice exposure, sharpness and composition', '2008-08-25 13:42:31.000000', NULL, 1),
(4909772, 713772, 14867, '<td valign="top">Good exposure...of the background!<br/>There are  almost no details in the subject itself</td>', 'Good exposure...of the background!There are  almost no details in the subject itself', '2008-08-25 13:42:55.000000', NULL, 1),
(4909775, 712654, 36999, '<td valign="top">funny that their ears flop all over when they shake.   I am endlessly amused by horse shakes.</td>', 'funny that their ears flop all over when they shake.   I am endlessly amused by horse shakes.', '2008-08-25 13:43:35.000000', NULL, 1),
(4909777, 712264, 14867, '<td valign="top">Nice capture of the motion, I would crop the building above though</td>', 'Nice capture of the motion, I would crop the building above though', '2008-08-25 13:45:51.000000', NULL, 1),
(4909780, 713550, 94614, '<td valign="top">I  really liked this shot- the bluish background is a nice contrast to the warm foreground. The shot itself definitely caught my eye- the composition is great and unique in this challenge.  Unfortunately it''s out of focus enough to be distracting. I''m rating a 6, but would definitely rate it higher if it were in focus enough to not distract my eye. Good Luck in the Challenge!</td>', 'I  really liked this shot- the bluish background is a nice contrast to the warm foreground. The shot itself definitely caught my eye- the composition is great and unique in this challenge.  Unfortunately it''s out of focus enough to be distracting. I''m rating a 6, but would definitely rate it higher if it were in focus enough to not distract my eye. Good Luck in the Challenge!', '2008-08-25 13:47:02.000000', NULL, 1),
(4909783, 713591, 94614, '<td valign="top">I liked the composition of this shot, but found that the front of the horses head being out of focus a bit distracting. Nice detail in the mane. Good luck in the challenge.</td>', 'I liked the composition of this shot, but found that the front of the horses head being out of focus a bit distracting. Nice detail in the mane. Good luck in the challenge.', '2008-08-25 13:49:33.000000', NULL, 1),
(4909786, 713725, 47791, '<td valign="top">This doesnt work against the noisy background. Which is a shame as you are definetely trying something different here.</td>', 'This doesnt work against the noisy background. Which is a shame as you are definetely trying something different here.', '2008-08-25 13:51:00.000000', NULL, 1),
(4909789, 713512, 56502, '<td valign="top">Definitely worth an extra point for the length you went to set up this shot!</td>', 'Definitely worth an extra point for the length you went to set up this shot!', '2008-08-25 13:52:50.000000', NULL, 1),
(4909790, 713153, 14867, '<td valign="top">Impressive capture, very difficult to obtain. The feeling of motion is perfect, but the horse is still visible too.</td>', 'Impressive capture, very difficult to obtain. The feeling of motion is perfect, but the horse is still visible too.', '2008-08-25 13:53:23.000000', NULL, 1),
(4909791, 713770, 94614, '<td valign="top">I like the lighting and the framing of the main subjects, but there are a couple of things that I thought might have taken away from the overall picture. 1. The focus could have been sharper   2. the alignment of the front horses head directly below the other horse''s posterior :)    Good luck in the challenge!</td>', 'I like the lighting and the framing of the main subjects, but there are a couple of things that I thought might have taken away from the overall picture. 1. The focus could have been sharper   2. the alignment of the front horses head directly below the other horse''s posterior :)    Good luck in the challenge!', '2008-08-25 13:53:58.000000', NULL, 1),
(4909793, 713763, 56502, '<td valign="top">Extra points for this one - this funny picture really made me chuckle.</td>', 'Extra points for this one - this funny picture really made me chuckle.', '2008-08-25 13:56:03.000000', NULL, 1),
(4909795, 712738, 94614, '<td valign="top">My absolute favorite in the challenge! 9! The composition is perfect, the silhouette manages to capture the feeling perfectly without needing any more detail, the clouds are awesome. This one goes directly into my favorites. Good Luck in the challenge! I hope to see this one on the front page.</td>', 'My absolute favorite in the challenge! 9! The composition is perfect, the silhouette manages to capture the feeling perfectly without needing any more detail, the clouds are awesome. This one goes directly into my favorites. Good Luck in the challenge! I hope to see this one on the front page.', '2008-08-25 13:56:34.000000', NULL, 1),
(4909800, 713164, 94614, '<td valign="top">I really liked this shot. The composition is great and unusual, the detail on the horse is great and the colors pop. That said, the slight halo around the horse and the metal bit(from oversharpening?) is distracting... still, a great shot 8.</td>', 'I really liked this shot. The composition is great and unusual, the detail on the horse is great and the colors pop. That said, the slight halo around the horse and the metal bit(from oversharpening?) is distracting... still, a great shot 8.', '2008-08-25 13:59:32.000000', NULL, 1),
(4909803, 713153, 94614, '<td valign="top">WOW. straight into favorites. Love the sense of flowing motion, the colors work beautifully- makes me want to run free too! 9! Good Luck in the Challenge</td>', 'WOW. straight into favorites. Love the sense of flowing motion, the colors work beautifully- makes me want to run free too! 9! Good Luck in the Challenge', '2008-08-25 14:01:04.000000', NULL, 1),
(4909806, 713553, 94614, '<td valign="top">awwww! great shot, colors and gorgeous detail- not to mention it makes me want to reach out and touch him- beautiful! 8..... almost a 9</td>', 'awwww! great shot, colors and gorgeous detail- not to mention it makes me want to reach out and touch him- beautiful! 8..... almost a 9', '2008-08-25 14:02:19.000000', NULL, 1),
