(4910113, 713650, 68586, '<td valign="top">Beautiful Horse captured at the perfect moment with tail and mane held high.</td>', 'Beautiful Horse captured at the perfect moment with tail and mane held high.', '2008-08-25 16:48:38.000000', NULL, 1),
(4910117, 713587, 68586, '<td valign="top">Tell number 3 to keep hold of his crop next time  :- )<br/> <br/>Nice shot - full of action and colour - good crop and framing.</td>', 'Tell number 3 to keep hold of his crop next time  :- ) Nice shot - full of action and colour - good crop and framing.', '2008-08-25 16:49:34.000000', NULL, 1),
(4910119, 713670, 93868, '<td valign="top">The logs in the lower left of the image as well as the yellowish bush are a bit distracting but I like the framing you did around the border. All that being said it''s stil a very nice image. Hope this helps.</td>', 'The logs in the lower left of the image as well as the yellowish bush are a bit distracting but I like the framing you did around the border. All that being said it''s stil a very nice image. Hope this helps.', '2008-08-25 16:50:02.000000', NULL, 1),
(4910124, 713245, 68586, '<td valign="top">Clever title - but the various elements don''t quite hold together for me . . the title appears to refer to the fly and the horse, but the reflection is possibly a stronger visual element, and the white of his eye draws the viewer away from both the previous aspects.<br/> <br/>There are lot''s of things in this shot - but for me they end up fighting for attention instead of working together.</td>', 'Clever title - but the various elements don''t quite hold together for me . . the title appears to refer to the fly and the horse, but the reflection is possibly a stronger visual element, and the white of his eye draws the viewer away from both the previous aspects. There are lot''s of things in this shot - but for me they end up fighting for attention instead of working together.', '2008-08-25 16:53:01.000000', NULL, 1),
(4910125, 713288, 93868, '<td valign="top">He''s got a horsie afro!!</td>', 'He''s got a horsie afro!!', '2008-08-25 16:53:39.000000', NULL, 1),
