(4910481, 712738, 59029, '<td valign="top">very cool silhouette, would''ve liked to see more of the horse. 7</td>', 'very cool silhouette, would''ve liked to see more of the horse. 7', '2008-08-25 18:58:29.000000', NULL, 1),
(4910487, 713525, 82707, '<td valign="top">Lovely image, and the composition and colour is great.  Nice DOF.  I would have preferred to have the board just a little lower, so that the bottom of the offside eye is not cropped off.</td>', 'Lovely image, and the composition and colour is great.  Nice DOF.  I would have preferred to have the board just a little lower, so that the bottom of the offside eye is not cropped off.', '2008-08-25 19:02:28.000000', NULL, 1),
(4910494, 713595, 45475, '<td valign="top">Beautiful. Crisp and clean.</td>', 'Beautiful. Crisp and clean.', '2008-08-25 19:10:50.000000', NULL, 1),
(4910495, 713052, 82707, '<td valign="top">Nice detail and colours, but I would prefer to see a bit wider crop around the head, or a square crop, with just the head!</td>', 'Nice detail and colours, but I would prefer to see a bit wider crop around the head, or a square crop, with just the head!', '2008-08-25 19:11:48.000000', NULL, 1),
(4910496, 712536, 45475, '<td valign="top">Interesting choice of angle and crop. Doesn''t feel like anything is in focus, yet it''s not overly blurred or unpleasant. I like it.</td>', 'Interesting choice of angle and crop. Doesn''t feel like anything is in focus, yet it''s not overly blurred or unpleasant. I like it.', '2008-08-25 19:13:05.000000', NULL, 1),
(4910497, 713289, 82707, '<td valign="top">Fabulous portrait!  What a beautiful animal!</td>', 'Fabulous portrait!  What a beautiful animal!', '2008-08-25 19:13:27.000000', NULL, 1),
(4910499, 713553, 45475, '<td valign="top">The epitome of pretty!</td>', 'The epitome of pretty!', '2008-08-25 19:13:52.000000', NULL, 1),
(4910501, 712677, 45475, '<td valign="top">Haha! Very cute. The horse is a star! Great work on comp, colour and light. Fantastic stuff.</td>', 'Haha! Very cute. The horse is a star! Great work on comp, colour and light. Fantastic stuff.', '2008-08-25 19:15:16.000000', NULL, 1),
(4910502, 713769, 45475, '<td valign="top">Nice, warm family feel to this. Good work.</td>', 'Nice, warm family feel to this. Good work.', '2008-08-25 19:16:04.000000', NULL, 1),
(4910505, 713601, 82707, '<td valign="top">Nice composition and sharp image, but the yellow hue spoils it a bit for me!</td>', 'Nice composition and sharp image, but the yellow hue spoils it a bit for me!', '2008-08-25 19:17:00.000000', NULL, 1),
(4910509, 713678, 45475, '<td valign="top">Perfect! Great stop action, just the right amount of dof to isolate the subject, beautiful light, strong contrast and colour... I suspect you already know this :)</td>', 'Perfect! Great stop action, just the right amount of dof to isolate the subject, beautiful light, strong contrast and colour... I suspect you already know this :)', '2008-08-25 19:18:06.000000', NULL, 1),
