(4910522, 713289, 45475, '<td valign="top">Not sure I''m comfortable with the angle of this shot. It''s almost as if you startled the horse. But aside from that and my compulsion to want to crop off the white blob at top-left, you nailed the dof, light and colour.</td>', 'Not sure I''m comfortable with the angle of this shot. It''s almost as if you startled the horse. But aside from that and my compulsion to want to crop off the white blob at top-left, you nailed the dof, light and colour.', '2008-08-25 19:21:47.000000', NULL, 1),
(4910523, 713550, 82707, '<td valign="top">A lovely moment!</td>', 'A lovely moment!', '2008-08-25 19:22:31.000000', NULL, 1),
(4910524, 713012, 82707, '<td valign="top">Lovely action shot!  The lighting is great!</td>', 'Lovely action shot!  The lighting is great!', '2008-08-25 19:22:43.000000', NULL, 1),
(4910525, 713582, 82707, '<td valign="top">Very cute! ...and amazing blue eyes.  Nice processing!</td>', 'Very cute! ...and amazing blue eyes.  Nice processing!', '2008-08-25 19:22:47.000000', NULL, 1),
