(4910591, 713507, 77196, '<td valign="top">This looks overprocessed to me - a yellowish cast, grass too light of a green.</td>', 'This looks overprocessed to me - a yellowish cast, grass too light of a green.', '2008-08-25 19:55:12.000000', NULL, 1),
(4910612, 713650, 45475, '<td valign="top">Interesting light. Raining? Lovely capture of this magnificent creature.</td>', 'Interesting light. Raining? Lovely capture of this magnificent creature.', '2008-08-25 20:04:12.000000', NULL, 1),
