(4910616, 713633, 45475, '<td valign="top">Creepy and disturbing. Strange how something as simple as angles and processing can make the innocent look sinister. Great stuff.</td>', 'Creepy and disturbing. Strange how something as simple as angles and processing can make the innocent look sinister. Great stuff.', '2008-08-25 20:08:00.000000', NULL, 1),
(4910618, 713738, 45475, '<td valign="top">Beautiful. Just needs a bit more contrast to give it punch and you''re away.</td>', 'Beautiful. Just needs a bit more contrast to give it punch and you''re away.', '2008-08-25 20:08:46.000000', NULL, 1),
(4910623, 713681, 45475, '<td valign="top">Very cool. Blowing out the white has eaten into some of the edges though.</td>', 'Very cool. Blowing out the white has eaten into some of the edges though.', '2008-08-25 20:10:09.000000', NULL, 1),
(4910632, 713715, 82707, '<td valign="top">Lovely image, the backlit dust creates a lovely atmosphere!  Bump 8</td>', 'Lovely image, the backlit dust creates a lovely atmosphere!  Bump 8', '2008-08-25 20:14:26.000000', NULL, 1),
