(4910683, 713516, 86447, '<td valign="top">Perfect stance.   Lovely horse.   Nice and Sharp.  I know it''s easier said than done, but I''d have liked to have seen this from the mane side.</td>', 'Perfect stance.   Lovely horse.   Nice and Sharp.  I know it''s easier said than done, but I''d have liked to have seen this from the mane side.', '2008-08-25 20:38:59.000000', NULL, 1),
(4910684, 713708, 86447, '<td valign="top">The wild eye distracts me from the rest of this being so wonderful.  I like your choice of PP.   Nice and sharp, too.</td>', 'The wild eye distracts me from the rest of this being so wonderful.  I like your choice of PP.   Nice and sharp, too.', '2008-08-25 20:39:06.000000', NULL, 1),
(4910685, 713310, 86447, '<td valign="top">Perfect sky for this angle!   Well done on the sharpness and timing the capture.</td>', 'Perfect sky for this angle!   Well done on the sharpness and timing the capture.', '2008-08-25 20:39:15.000000', NULL, 1),
