INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4910968, 713575, 88136, '<td valign="top">what a great photo! this is fantastic-8</td>', 'what a great photo! this is fantastic-8', '2008-08-25 22:08:42.000000', NULL, 1),
(4910969, 713768, 43463, '<td valign="top">Love how the fish-eye lens works in this composition. It really makes the horse visually pop out the viewer. Colors are vivid and details are nice and sharp. Shot is taken at a slight angle too which gives the gives the appearance of the main subject appearing on the diagonal. Not sure if that is a good or bad thing but it does add some visual interest. Now onto areas where I think that this image needs some improvement. First, expressions can really give a composition that added ''omph'' to make it more eye-catching. I see a bit of the horse''s eye and his/her expression a bit but not the rider. For the image to be more visually appealing AND play into the title you need to show us the girl''s face. Show us her joy and delight at riding the horse. Help us make a connection. Not doing so I feel is the major weakness of the composition. Had you captured a joyful expression by showing the little girl''s face it would have moved the score from a just above average shot into the stellar category. A minor flaw is that there is an odd shadow that appears over the chest of the horse. Personally, I would have loved to have seen more of this horse''s beautiful coloration.</td>', 'Love how the fish-eye lens works in this composition. It really makes the horse visually pop out the viewer. Colors are vivid and details are nice and sharp. Shot is taken at a slight angle too which gives the gives the appearance of the main subject appearing on the diagonal. Not sure if that is a good or bad thing but it does add some visual interest. Now onto areas where I think that this image needs some improvement. First, expressions can really give a composition that added ''omph'' to make it more eye-catching. I see a bit of the horse''s eye and his/her expression a bit but not the rider. For the image to be more visually appealing AND play into the title you need to show us the girl''s face. Show us her joy and delight at riding the horse. Help us make a connection. Not doing so I feel is the major weakness of the composition. Had you captured a joyful expression by showing the little girl''s face it would have moved the score from a just above average shot into the stellar category. A minor flaw is that there is an odd shadow that appears over the chest of the horse. Personally, I would have loved to have seen more of this horse''s beautiful coloration.', '2008-08-25 22:09:06.000000', NULL, 1),
(4910970, 713052, 88136, '<td valign="top">what a cute little guy. great color and texture-7</td>', 'what a cute little guy. great color and texture-7', '2008-08-25 22:09:09.000000', NULL, 1),
(4910972, 713583, 88136, '<td valign="top">this is a great photo. fantastic capture, great texture and color-10</td>', 'this is a great photo. fantastic capture, great texture and color-10', '2008-08-25 22:10:22.000000', NULL, 1),
