(4912314, 712738, 3746, '<td valign="top">nice and atmospheric.. hope it does well for you.</td>', 'nice and atmospheric.. hope it does well for you.', '2008-08-26 15:23:57.000000', NULL, 1),
(4912322, 713245, 3746, '<td valign="top">OK, initially I thought this shot came across as a bit snapshotty. BUT... The sense of scale here is actually stunning, especially being able to see the Flys eyes as well, and the reflection of the horse is a nice little touch that will probably be missed by some voters.. however, saying that, the border doesnt do this shot any favours, and maybe some selective contrast would of made the whole shot tighter.. Still, the idea is good and the reflection is a nice little touch.. well done!</td>', 'OK, initially I thought this shot came across as a bit snapshotty. BUT... The sense of scale here is actually stunning, especially being able to see the Flys eyes as well, and the reflection of the horse is a nice little touch that will probably be missed by some voters.. however, saying that, the border doesnt do this shot any favours, and maybe some selective contrast would of made the whole shot tighter.. Still, the idea is good and the reflection is a nice little touch.. well done!', '2008-08-26 15:27:16.000000', NULL, 1),
(4912327, 713174, 3746, '<td valign="top">Hmmmm, when this shot first popped up my immediate thought was "ACK!! Overprocessed!", however after viewing for a bit longer one can apprieciate the fairytaleness in this shot and the processing actually compliments it, and that tail really adds to the shot.. not bad at all really!!</td>', 'Hmmmm, when this shot first popped up my immediate thought was "ACK!! Overprocessed!", however after viewing for a bit longer one can apprieciate the fairytaleness in this shot and the processing actually compliments it, and that tail really adds to the shot.. not bad at all really!!', '2008-08-26 15:28:38.000000', NULL, 1),
(4912329, 713587, 3746, '<td valign="top">Not a fan of the processing here, it looks like Lucisarts or too much EHDR.  Nice stopped motion though and the focus and lighting is pretty well nailed.</td>', 'Not a fan of the processing here, it looks like Lucisarts or too much EHDR.  Nice stopped motion though and the focus and lighting is pretty well nailed.', '2008-08-26 15:30:08.000000', NULL, 1),
