(4920731, 713012, 45524, '<td valign="top">Nice side light to bring interesting shadows. I''m not so sure about the background element on the right, it wants to draw my eye.</td>', 'Nice side light to bring interesting shadows. I''m not so sure about the background element on the right, it wants to draw my eye.', '2008-08-29 23:47:35.000000', NULL, 1),
(4920736, 713732, 45524, '<td valign="top">This could have been a very good photo. I dont like the fact that the rider is cut off badly. The focus and action are nice, but with the rider cut off as it is I dont like it.</td>', 'This could have been a very good photo. I dont like the fact that the rider is cut off badly. The focus and action are nice, but with the rider cut off as it is I dont like it.', '2008-08-29 23:49:45.000000', NULL, 1),
(4920738, 713542, 45524, '<td valign="top">Now this I really like. The wide angle, the background, the subject, yes this is nice.</td>', 'Now this I really like. The wide angle, the background, the subject, yes this is nice.', '2008-08-29 23:50:59.000000', NULL, 1),
(4920739, 713125, 45524, '<td valign="top">What a pretty setting. The interaction of the two subjects with a pleasing background.</td>', 'What a pretty setting. The interaction of the two subjects with a pleasing background.', '2008-08-29 23:51:31.000000', NULL, 1),
