(4920753, 712708, 45524, '<td valign="top">Tough backlighting. Appears as though the shadows were lost in the exposure and brought back. Really hurting the contrast in the photo.</td>', 'Tough backlighting. Appears as though the shadows were lost in the exposure and brought back. Really hurting the contrast in the photo.', '2008-08-29 23:56:56.000000', NULL, 1),
(4920754, 713573, 45524, '<td valign="top">LOL while this makes me laugh. Which I''m sure was your intentions. The photo lacks much beyond amusement to keep the viewers attention.</td>', 'LOL while this makes me laugh. Which I''m sure was your intentions. The photo lacks much beyond amusement to keep the viewers attention.', '2008-08-29 23:58:46.000000', NULL, 1),
