(4923492, 713012, 83416, '<td valign="top">Great! Love what you did with the lighting/shadows and how you captured the beauty of the animal in motion! The only minor comment  the bright wall in the back is a bit too bright in my opinion. Either way  wishing your entry a great finish!</td>', 'Great! Love what you did with the lighting/shadows and how you captured the beauty of the animal in motion! The only minor comment  the bright wall in the back is a bit too bright in my opinion. Either way  wishing your entry a great finish!', '2008-08-31 19:47:38.000000', NULL, 1),
(4923498, 713727, 83416, '<td valign="top">Beautiful! Nothing unusual in the horses pose but lighting, composition and post-processing results in an excellent image!</td>', 'Beautiful! Nothing unusual in the horses pose but lighting, composition and post-processing results in an excellent image!', '2008-08-31 19:53:31.000000', NULL, 1),
(4923503, 712197, 83416, '<td valign="top">The whole image and the animal - coming straight from a fairy tale! Great entry!</td>', 'The whole image and the animal - coming straight from a fairy tale! Great entry!', '2008-08-31 19:56:21.000000', NULL, 1),
