(4923515, 713512, 83416, '<td valign="top">Very creative entry! The background takes away a bit from the dream effect. Still great!!!</td>', 'Very creative entry! The background takes away a bit from the dream effect. Still great!!!', '2008-08-31 20:06:57.000000', NULL, 1),
(4923519, 713575, 83416, '<td valign="top">The title, composition, lighting and processing all works well together.</td>', 'The title, composition, lighting and processing all works well together.', '2008-08-31 20:09:15.000000', NULL, 1),
(4923520, 713671, 83416, '<td valign="top">Perfect timing with lighting!</td>', 'Perfect timing with lighting!', '2008-08-31 20:09:50.000000', NULL, 1),
