INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4925236, 713012, 15711, '<td valign="top">I had this as a ribbon winner for sure.  Great shot.</td>', 'I had this as a ribbon winner for sure.  Great shot.', '2008-09-01 10:55:43.000000', NULL, 0),
(4925237, 712940, 65319, '<td valign="top">I''m very disappointed to see where this one landed.  I love, Love, LOVE this one!</td>', 'I''m very disappointed to see where this one landed.  I love, Love, LOVE this one!', '2008-09-01 10:56:14.000000', NULL, 0),
(4925243, 713594, 58728, '<td valign="top">Completely underrated.  I LOVE this shot.  I gave it an 8 during voting.  it''s a lovely shot, and you processed it beautifully.</td>', 'Completely underrated.  I LOVE this shot.  I gave it an 8 during voting.  it''s a lovely shot, and you processed it beautifully.', '2008-09-01 10:57:09.000000', NULL, 0),
(4925264, 713594, 65319, '<td valign="top">The dappled lighting is just lovely!  The clouds above and the breeze in his mane give a perfect impression of a lovely Summer''s day.  The dark contrasty grass lends drama to the softer gentle lighting of the horsey.  Well Done!</td>', 'The dappled lighting is just lovely!  The clouds above and the breeze in his mane give a perfect impression of a lovely Summer''s day.  The dark contrasty grass lends drama to the softer gentle lighting of the horsey.  Well Done!', '2008-09-01 11:01:42.000000', NULL, 0),
(4925279, 713028, 66384, '<td valign="top">A lovely addition to your top row. I love the texture in this shot. It seems like I can put my hands on her muzzle and feel the soft skin.</td>', 'A lovely addition to your top row. I love the texture in this shot. It seems like I can put my hands on her muzzle and feel the soft skin.', '2008-09-01 11:07:42.000000', NULL, 0),
(4925296, 713594, 66384, '<td valign="top">Nice effect of the b&amp;w, and I like the wind in the mane and the lines of the horse''s head and neck circling around. Thanks for the b&amp;w conversion tip.</td>', 'Nice effect of the b&w, and I like the wind in the mane and the lines of the horse''s head and neck circling around. Thanks for the b&w conversion tip.', '2008-09-01 11:12:44.000000', NULL, 0),
(4925310, 713587, 79720, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by snaffles:</b></div><hr/><i> LOL quite a few of us noticed the crop drop! :-) </i></td></tr></table> <br/>haha, yeah...I''m thinking the person who gave me a 2 thought that ruined the shot! <b>:</b>-P</td>', 'Originally posted by snaffles: LOL quite a few of us noticed the crop drop! :-)  haha, yeah...I''m thinking the person who gave me a 2 thought that ruined the shot! :-P', '2008-09-01 11:17:44.000000', NULL, 0),
(4925313, 713770, 73564, '<td valign="top">my god, I don''t know how I didn''t realize this was so oof, oh well.</td>', 'my god, I don''t know how I didn''t realize this was so oof, oh well.', '2008-09-01 11:18:39.000000', NULL, 0),
(4925339, 712940, 30982, '<td valign="top">I for one am very pleased you entered this.  One of the most powerful entries in the challenge - you definitely captured the spirit and power of a horse.  Your choices in crop and processing really add to this.  One of my 10s.</td>', 'I for one am very pleased you entered this.  One of the most powerful entries in the challenge - you definitely captured the spirit and power of a horse.  Your choices in crop and processing really add to this.  One of my 10s.', '2008-09-01 11:29:23.000000', NULL, 0),
(4925341, 713153, 30982, '<td valign="top">YAY!!  13th is my favorite placing, you know.  EXCELLENT shot (but I already told you that) and very pleased to see this place so high!</td>', 'YAY!!  13th is my favorite placing, you know.  EXCELLENT shot (but I already told you that) and very pleased to see this place so high!', '2008-09-01 11:32:30.000000', NULL, 0),
